export const languages = [
  { code: 'en', name: 'English' }, { code: 'fr', name: 'Français' }, { code: 'de', name: 'Deutsch' },
  { code: 'it', name: 'Italiano' }, { code: 'es', name: 'Español' }
];

let current = 'en';

export function detectLanguage() {
  for (const l of navigator.languages || [navigator.language || 'en']) {
    const code = String(l).slice(0, 2).toLowerCase();
    if (texts[code]) return code;
  }
  return 'en';
}

export function setLanguage(code) {
  current = texts[code] ? code : detectLanguage();
  document.documentElement.lang = current;
}

export function language() { return current; }

export function t(key, vars) {
  let s = (texts[current] && texts[current][key]) || texts.en[key] || key;
  if (vars) for (const k of Object.keys(vars)) s = s.split('{' + k + '}').join(String(vars[k]));
  return s;
}
